ATL_SRC.push(['@atl/forms/otifemail.js', 0, `// OTIF & Quality incident → email to upper management. After a new OTIF Log entry is saved, a prompt offers an Outlook
// draft (.eml): the incident report in the body and the same report attached as a Word file, ready to send. Any entry
// can be emailed again from its edit form ("✉ Email this incident to management"). Recipients are remembered
// (Settings ▸ otifEmailTo for admins, otherwise this browser).
import { store } from '@atl/store.js';
import { derive } from '@atl/calc.js';
import { esc, toast, downloadBlob, norm, todayISO } from '@atl/util.js';
import { openEmail } from '@atl/forms/email.js';
import { reportDocx } from '@atl/forms/elxreport.js';
import { linkedReport, isRecordableType } from '@atl/forms/incident.js';
import { archiveSent } from '@atl/forms/archive.js';

const KEY = 'atl-otif-email-to';
const DOCX = 'application/vnd.openxmlformats-officedocument.wordprocessingml.document';
const us = iso => (iso ? \`\${+iso.slice(5, 7)}/\${+iso.slice(8, 10)}/\${iso.slice(0, 4)}\` : '');
const money = v => (v === '' || v == null || isNaN(+v) ? '' : '$' + (+v).toLocaleString('en-US', { maximumFractionDigits: 2 }));

export function otifEmailTo() {
  let to = store.settings?.otifEmailTo || '';
  try { to ||= localStorage.getItem(KEY) || ''; } catch {}
  return to;
}
async function rememberTo(to) {
  if (!to) return;
  try { localStorage.setItem(KEY, to); } catch {}
  if (store.can('admin') && to !== (store.settings.otifEmailTo || '')) await store.saveConfig('settings', { ...store.settings, otifEmailTo: to });
}

/** The entry with its calculated columns (Month, Counts in Accuracy %) when available. */
const full = row => ({ ...row, ...(derive('otif').find(r => r.id === row.id) || {}) });

/** Month-to-date and year-to-date context for the customer and the building. */
function context(r) {
  const all = store.rows('otif'), m = String(r.date || '').slice(0, 7), y = m.slice(0, 4);
  const same = (a, b) => norm(a) === norm(b);
  const n = f => all.filter(f).length;
  return {
    custMonth: n(o => same(o.customer, r.customer) && String(o.date).startsWith(m)),
    custYear: n(o => same(o.customer, r.customer) && String(o.date).startsWith(y)),
    bldgMonth: n(o => String(o.facility) === String(r.facility) && String(o.date).startsWith(m)),
    catMonth: n(o => same(o.category, r.category) && String(o.date).startsWith(m)),
  };
}

/** Report fields: [label, value] — blanks dropped. */
function fields(r) {
  const sf = isRecordableType(r.type) ? linkedReport(r.id) : null;
  return [['Incident ID', r.id], ['Date', us(r.date)], ['Facility', r.facility], ['Customer', r.customer], ['Incident type', r.type], ['Category', r.category],
    ['Responsible party', r.responsible], ['Counts in accuracy %', r.counts], ['Status', r.status], ['Est. cost impact', money(r.cost)], ['CAPA / Ref #', r.capa],
    ['Safety Incident report', sf ? sf.id : isRecordableType(r.type) ? 'Required — not yet filed' : ''], ['Logged by', r.loggedBy || store.user?.name || '']].filter(([, v]) => v !== '' && v != null);
}
const subjectOf = r => \`OTIF Incident \${r.id} — \${[r.type, r.category].filter(Boolean).join(' / ')} — \${r.customer || ''} — \${r.facility || ''} — \${us(r.date)}\`.replace(/ — (?= —)| — $/g, '');

/** Word report (built with the Electrolit report's Word writer). */
function docx(r) {
  const c = context(r), b = [];
  b.push({ t: 'h1', text: \`OTIF & Quality Incident Report — \${r.id}\` });
  b.push({ t: 'note', text: \`Piper Warehouse · Facility \${r.facility || ''} · prepared \${us(todayISO())}\` });
  b.push({ t: 'table', widths: [3000, 7080], head: ['Field', 'Details'], rows: fields(r) });
  for (const [h, v] of [['Incident description', r.description], ['Root cause', r.rootCause], ['Corrective action', r.corrective]]) {
    b.push({ t: 'h2', text: h });
    b.push({ t: 'p', text: v || 'Not entered yet.' });
  }
  b.push({ t: 'h2', text: 'Context' });
  b.push({ t: 'bullets', items: [\`\${c.custMonth} OTIF incident\${c.custMonth === 1 ? '' : 's'} for \${r.customer || 'this customer'} this month (\${c.custYear} this year).\`,
    \`\${c.bldgMonth} OTIF incident\${c.bldgMonth === 1 ? '' : 's'} in building \${r.facility || ''} this month.\`, \`\${c.catMonth} “\${r.category || 'uncategorised'}” incident\${c.catMonth === 1 ? '' : 's'} this month across both buildings.\`] });
  return reportDocx(b, \`OTIF Incident \${r.id} · Piper Warehouse\`);
}

/** Outlook draft with the report in the body and attached. */
export async function emailOtif(row, to = otifEmailTo()) {
  const r = full(row), c = context(r);
  const td = 'padding:5px 10px;border:1px solid #d5dbe4;vertical-align:top';
  const block = (h, v) => \`<h3 style="margin:14px 0 4px;color:#16325c;font-size:12pt">\${esc(h)}</h3><p style="margin:0">\${v ? esc(v).replace(/\\n/g, '<br>') : '<i style="color:#8a97a8">Not entered yet.</i>'}</p>\`;
  const html = \`<div style="font-family:Calibri,Arial,sans-serif;font-size:11pt;color:#1c232d">
    <p>An OTIF / quality incident was logged on the OTIF Log. Details below; the report is attached.</p>
    <div style="background:#16325c;color:#fff;padding:8px 12px;font-weight:700;font-size:13pt;border-bottom:3px solid #c0392b">OTIF &amp; Quality Incident Report — \${esc(r.id)}</div>
    <table style="border-collapse:collapse;font-size:10.5pt;margin:8px 0 6px;min-width:420px">\${fields(r).map(([k, v]) => \`<tr><td style="\${td};font-weight:700;background:#f4f6f9;white-space:nowrap">\${esc(k)}</td><td style="\${td}">\${esc(v)}</td></tr>\`).join('')}</table>
    \${block('Incident description', r.description)}\${block('Root cause', r.rootCause)}\${block('Corrective action', r.corrective)}
    <h3 style="margin:14px 0 4px;color:#16325c;font-size:12pt">Context</h3><ul style="margin:0;padding-left:20px">
      <li>\${c.custMonth} OTIF incident\${c.custMonth === 1 ? '' : 's'} for \${esc(r.customer || 'this customer')} this month (\${c.custYear} this year)</li>
      <li>\${c.bldgMonth} in building \${esc(r.facility || '')} this month</li><li>\${c.catMonth} “\${esc(r.category || 'uncategorised')}” this month across both buildings</li></ul>
    <p style="margin-top:16px">Thank you,<br>\${esc(store.user?.name || '')}</p></div>\`;
  const bytes = new Uint8Array(await docx(r).arrayBuffer());
  const subject = subjectOf(r);
  const attachments = [[\`OTIF Incident Report \${r.id}.docx\`, bytes, DOCX]];
  openEmail({ to, subject, html, attachments });
  await archiveSent({ kind: 'otif', building: r.facility, fileDate: r.date, title: subject.replace(/^OTIF Incident /, ''), subject, to, html, attachments, ref: r.id });
  await rememberTo(to);
  if (store.can('edit') && r.id) await store.update('otif', r.id, { emailedAt: new Date().toISOString(), emailedTo: to }).catch(() => {});
}

/** Prompt after a new OTIF entry (required: no Cancel, Escape blocked); from an entry's edit form it can be cancelled. */
export function promptOtifEmail(row, { required = false } = {}) {
  document.querySelector('.otif-ask-back')?.remove();
  const r = full(row);
  const el = document.createElement('div');
  el.className = 'modal-back otif-ask-back';
  el.innerHTML = \`<form class="modal inc-ask otif-ask" role="dialog" aria-modal="true" aria-labelledby="otif-ask-t">
    <div class="inc-ask-top"><span class="inc-ask-icon otif" aria-hidden="true">✉</span><h2 id="otif-ask-t">Email this OTIF incident to upper management</h2></div>
    <p><b>\${esc(r.id)}</b> — \${esc([r.type, r.category].filter(Boolean).join(' / '))} · \${esc(r.customer || '')} · \${esc(r.facility || '')} · \${esc(us(r.date))}</p>
    \${required ? '<p class="inc-required"><b>Required.</b> Every OTIF incident must be reported to upper management.</p>' : ''}
    <p class="muted small">Downloads an Outlook draft with the incident report in the message and the Word report attached — open it, check it and press Send.</p>
    <label class="otif-to">To <input type="text" name="to" value="\${esc(otifEmailTo())}" placeholder="manager@company.com; …" aria-label="Email recipients"></label>
    <div class="inc-ask-foot">\${required ? '' : '<button type="button" class="btn ghost" data-later>Cancel</button>'}<button type="submit" class="btn primary">✉ Create email</button></div></form>\`;
  document.body.appendChild(el);
  const close = () => el.remove();
  el.querySelector('[data-later]')?.addEventListener('click', close);
  // New entries: no way to skip — Escape does not close it.
  el.addEventListener('keydown', e => { if (e.key !== 'Escape') return; if (required) { e.preventDefault(); toast('Reporting to upper management is required: click “Create email”', 'bad'); } else close(); });
  el.querySelector('form').addEventListener('submit', async e => {
    e.preventDefault();
    const btn = e.submitter || el.querySelector('[type=submit]'); btn.disabled = true;
    try { await emailOtif(r, e.target.elements.to.value.trim()); close(); toast('Outlook draft downloaded — open it (click it in the browser’s downloads) and the email opens with the report attached, ready to send'); }
    catch (err) { btn.disabled = false; toast(err.message, 'bad'); }
  });
  setTimeout(() => el.querySelector('[type=submit]').focus(), 30);
}

// "✉ Email this incident to management" link in an OTIF entry's edit form.
document.addEventListener('click', e => {
  const a = e.target.closest?.('[data-otif-email]'); if (!a) return;
  e.preventDefault();
  const row = store.rows('otif').find(r => r.id === a.dataset.otifEmail);
  if (row) promptOtifEmail(row);
});`]);

