    $$('[data-href]', root).forEach(tr => { tr.addEventListener('click', e => { if (!e.target.closest('a,button,input,select')) location.hash = tr.dataset.href; }); tr.addEventListener('keydown', e => { if (e.key === 'Enter') location.hash = tr.dataset.href; }); });
    $$('[data-set-sup]', root).forEach(s => s.addEventListener('change', () => { st.sup = s.value; go({ sup: s.value }); }));
    const fm = $('[data-filters]', root);
    if (fm) { fm.addEventListener('change', () => { const d = Object.fromEntries(new FormData(fm)); Object.assign(st, d); go(d); }); $('[data-clear]', fm)?.addEventListener('click', () => { Object.assign(st, { sup: '', building: '', type: '', status: '', from: '', to: '', period: 'month', anchor: '' }); location.hash = link({ tab: tab || 'overview' }); }); }
    // Session page: handout downloads, record, planned date.
    const s = sessionOf(q.code || '');
    if (s) {
      $('[data-word]', root)?.addEventListener('click', () => handoutWord(s).catch(e => toast(e.message, 'bad')));
      $('[data-print]', root)?.addEventListener('click', () => handoutPrint(s).catch(e => toast(e.message, 'bad')));
      const sup = q.sup || defaultSup(), so = supervisors().find(x => x.name === sup), sch = so ? scheduleFor(so).find(x => x.code === q.code) : null;
      if (sch) {
        $('[data-record]', root)?.addEventListener('click', () => recordForm(sch, rerender));
        $('[data-plan]', root)?.addEventListener('click', async () => { const v = prompt('Planned date (YYYY-MM-DD)', recordOf(sch.id)?.plannedDate || sch.start); if (v === null) return; if (v && !isISO(v)) return toast('Use the format YYYY-MM-DD', 'bad'); await saveRecord(sch, { plannedDate: v }); toast('Planned date saved'); });
        if (q.record === '1' && canRecord(sup) && !document.querySelector('.tr-form')) { history.replaceState(null, '', location.hash.replace(/&record=1/, '')); recordForm(sch, rerender); }
      }
    }
    $$('[data-word-doc]', root).forEach(b => b.addEventListener('click', () => handoutWord(PROGRAM.docs[+b.dataset.wordDoc]).catch(e => toast(e.message, 'bad'))));
    $$('[data-print-doc]', root).forEach(b => b.addEventListener('click', () => handoutPrint(PROGRAM.docs[+b.dataset.printDoc]).catch(e => toast(e.message, 'bad'))));
    drawHandouts(root);
