    $$('[data-tdrop]', root).forEach(z => {
      const go = list => { if (list?.length) import('@atl/views/trainscanui.js').then(m => m.openTrainingDrop(list, { code: z.dataset.code, sup: z.dataset.sup })); };
      const inp = $('[data-tfile]', z);
      inp.addEventListener('change', () => { go([...inp.files]); inp.value = ''; });
      z.addEventListener('keydown', e => { if (e.key === 'Enter' || e.key === ' ') { e.preventDefault(); inp.click(); } });
      z.addEventListener('dragover', e => { e.preventDefault(); z.classList.add('over'); });
      z.addEventListener('dragleave', () => z.classList.remove('over'));
      z.addEventListener('drop', e => { e.preventDefault(); e.stopPropagation(); z.classList.remove('over'); go([...e.dataTransfer.files]); });
    });
